				var textView *cocoa.NSTextView = castcocoaNSViewTococoaNSTextView(this.View)
				var range_ cocoa.NSRange = textView.SelectedRange()
				var str *cocoa.NSString = this.GetInsertString(oldText, range_)
				textView.ReplaceCharactersInRange(range_, str)
